import{_ as a,o as t,c as o,S as r}from"./chunks/framework.D1Ss-Xl7.js";const S=JSON.parse('{"title":"前端开发的技术栈","description":"我发现自己博客没次开头都是在说近况和废话。这次也不例外。哈哈哈，工作也算顺畅，顺便总结下最近的前端开发的技术栈来回顾下这半年学到的知识。","frontmatter":{"title":"前端开发的技术栈","date":"2017-11-18 17:18","comments":true,"archives":2017,"tags":["frontend"]},"headers":[],"relativePath":"posts/2017-11-18-frontend-development/index.md","filePath":"posts/2017/2017-11-18-frontend-development.md"}'),c={name:"posts/2017-11-18-frontend-development/index.md"};function d(s,e,n,i,p,l){return t(),o("div",null,[...e[0]||(e[0]=[r('<p>我发现自己博客没次开头都是在说近况和废话。这次也不例外。哈哈哈，工作也算顺畅，顺便总结下最近的前端开发的技术栈来回顾下这半年学到的知识。</p><h2 id="html-开发" tabindex="-1">HTML 开发 <a class="header-anchor" href="#html-开发" aria-label="Permalink to &quot;HTML 开发&quot;">​</a></h2><p>对于大型项目，直接书写 HTML 代码是一个非常繁琐和头疼的事情，因为 HTML 需要闭合，每次找匹配的 HTML 标签都要非常花功夫。所以现在的开发都是使用预处理器来书写代码，例如主流的<a href="https://github.com/pugjs/pug" target="_blank" rel="noreferrer">Pug</a>，通过缩进来控制元素的嵌套，还支持多种语法。非常适合大型项目的开发，再也不用担心修改代码的时候出现 HTML 元素标签没有闭合的情况发生了。而且还规避了一些语法错误，例如在<code>p</code>标签里嵌入<code>block</code>元素是非法的。如果强行嵌入的话，你会发现生成的 HTML 代码是错误的。</p><h2 id="css-开发" tabindex="-1">CSS 开发 <a class="header-anchor" href="#css-开发" aria-label="Permalink to &quot;CSS 开发&quot;">​</a></h2><p>CSS 开发更多的需要是良好的模块化功能和合理的作用域。这时候也需要通过预处理器来进行操作，推荐使用<a href="http://sass-lang.com/guide" target="_blank" rel="noreferrer">SCSS</a>。这里很多人对<code>sass</code>和<code>scss</code>之间的区别有疑问。简单的来说，<code>SCSS</code>的格式更接近 CSS，所以比较容易上手。但是<code>SASS</code>是通过缩进来书写的，对新手不太友好。所以建议大家使用<code>SCSS</code>来书写模块化代码。</p><h2 id="javascript-开发" tabindex="-1">JavaScript 开发 <a class="header-anchor" href="#javascript-开发" aria-label="Permalink to &quot;JavaScript 开发&quot;">​</a></h2><p>现在主流的浏览器支持的 JavaScript 版本是 es5。但是众所周知，JavaScript(es5)有很多陷阱和缺点，例如<code>this</code>指针问题和异步处理等等。基于原型连的继承对于面向对象开发者来说也很不友好。所以推荐使用<a href="http://es6-features.org/#Constants" target="_blank" rel="noreferrer">es6</a>来书写代码。可以使用基于<code>class</code>的继承，和解决<code>this</code>指针问题。而且还能使用<code>import</code>进行模块化开发。虽然只是语法糖，但也提升了开发效率。</p><h2 id="自动化构建工具" tabindex="-1">自动化构建工具 <a class="header-anchor" href="#自动化构建工具" aria-label="Permalink to &quot;自动化构建工具&quot;">​</a></h2><p>我们使用了预处理器来书写代码，并使用新版本的<code>es6</code>语法。但是目前浏览器并不支持直接解析这些内容。所以我们需要构建化工具来处理从 Pug 生成 HTML，从 SCSS 生成 CSS，把 es6 语法的 JavaScript 转换成 es5 语法。对于 SPA 网站推荐使用<code>webpack</code>，而对于普通网站的构建推荐使用<code>Gulp</code>。这里区别开的原因是，<code>webpack</code>必须指定入口文件，但是<code>Gulp</code>只需要指定需要处理的文件或文件夹就可以了，支持通配符匹配。对于多页面的传统网站来说非常便利。</p><h2 id="浏览器兼容处理" tabindex="-1">浏览器兼容处理 <a class="header-anchor" href="#浏览器兼容处理" aria-label="Permalink to &quot;浏览器兼容处理&quot;">​</a></h2><p>这是每个前端工程师最头疼的地方了，因为每个浏览器支持程度都不一样。在使用比较新的 API 记得去<a href="https://caniuse.com/" target="_blank" rel="noreferrer">Can I use</a>查看下各个浏览器的支持情况，如果实在是需要这个功能的话，那就只能去寻找<code>polyfill</code>了。</p><p>参考：</p><p><a href="https://stackoverflow.com/questions/8397852/why-p-tag-cant-contain-div-tag-inside-it" target="_blank" rel="noreferrer">Why p tag can&#39;t contain div tag</a></p>',13)])])}const f=a(c,[["render",d]]);export{S as __pageData,f as default};
